export interface Totp_secret {
  id: number;
  did: string;
  secret: string;
  period: number;
  digits: number;
  created_at: string;
  updated_at: string;
}

export interface CreateTotp_secretDto {
  did: string;
  secret: string;
  period: number;
  digits: number;
}

export interface UpdateTotp_secretDto {
  did?: string;
  secret?: string;
  period?: number;
  digits?: number;
}

export interface Totp_secretSearchParams {
  q?: string;
  cursor?: string;
  limit?: number;
  count?: string;
  sort?: string;
  order?: 'asc' | 'desc';
  page?: number;
  created_at_from?: string;
  created_at_to?: string;
  updated_at_from?: string;
  updated_at_to?: string;
}

export interface Totp_secretCursorPage {
  data: Totp_secret[];
  nextCursor: string | null;
  hasMore: boolean;
  total?: number;
}

import db from '../../db';
import type { Totp_secret, CreateTotp_secretDto, UpdateTotp_secretDto, Totp_secretSearchParams, Totp_secretCursorPage } from './totp_secret.types';

// Strip internal fields before returning to clients
const strip = ({ project_id: _, ...rest }: any): Totp_secret => rest;

export const getAll = async (projectId: string, params: Totp_secretSearchParams): Promise<Totp_secretCursorPage> => {
  const limit = Number(params.limit) || 20;
  const SORTABLE_COLS = new Set<string>(['id', 'did', 'secret', 'period', 'digits', 'created_at', 'updated_at']);
  const sortCol = params.sort && SORTABLE_COLS.has(params.sort) ? params.sort : 'id';
  const sortDir = params.order === 'desc' ? 'desc' : 'asc';

  const base = db('totp_secrets').where({ project_id: projectId }).whereNull('deleted_at').orderBy(sortCol, sortDir);
  if (sortCol === 'id') {
    if (params.cursor) base.where('id', '>', Number(params.cursor));
  } else {
    const pg = Number(params.page) || 1;
    base.offset((pg - 1) * limit);
  }

  if (params.created_at_from) base.where('created_at', '>=', params.created_at_from);
  if (params.created_at_to) base.where('created_at', '<=', params.created_at_to);
  if (params.updated_at_from) base.where('updated_at', '>=', params.updated_at_from);
  if (params.updated_at_to) base.where('updated_at', '<=', params.updated_at_to);
  const rows = await base.clone().limit(limit + 1);
  const hasMore = rows.length > limit;
  const data = (hasMore ? rows.slice(0, limit) : rows).map(strip);
  const nextCursor = hasMore ? String(data[data.length - 1].id) : null;

  let total: number | undefined;
  if (params.count === 'true') {
    const countRow = await base.clone().count('* as count').first();
    total = Number((countRow as any).count);
  }

  return { data, nextCursor, hasMore, total };
};

export const getById = async (projectId: string, id: number): Promise<Totp_secret | undefined> => {
  const row = await db('totp_secrets').where({ id, project_id: projectId }).whereNull('deleted_at').first();
  return row ? strip(row) : undefined;
};

export const create = async (projectId: string, data: CreateTotp_secretDto): Promise<Totp_secret> => {
  const [id] = await db('totp_secrets').insert({ ...data, project_id: projectId });
  return getById(projectId, id) as Promise<Totp_secret>;
};

export const update = async (projectId: string, id: number, data: UpdateTotp_secretDto): Promise<Totp_secret | undefined> => {
  await db('totp_secrets').where({ id, project_id: projectId }).update({ ...data, updated_at: new Date().toISOString() });
  return getById(projectId, id);
};

export const remove = async (projectId: string, id: number): Promise<void> => {
  await db('totp_secrets').where({ id, project_id: projectId }).whereNull('deleted_at').update({ deleted_at: new Date().toISOString() });
};

